_MISSING = object()

def _early_valid(owner, now):
    return owner.get("scope") == "PUBLISHER" and owner.get("expires_at", float("-inf")) > now()

def _identity(owner):
    return tuple(owner.get(key, _MISSING) for key in ("owner_id", "token", "acquired_at"))

def publish(value, owner, prepare, now, output):
    if not _early_valid(owner, now):
        return False
    identity = _identity(owner)
    prepared = prepare(value)
    if _identity(owner) != identity or not _early_valid(owner, now):
        return False
    output.append(prepared)
    return True

def merge(value, owner, prepare, now, output):
    if not _early_valid(owner, now):
        return False
    identity = _identity(owner)
    prepared = prepare(value)
    if _identity(owner) != identity or not _early_valid(owner, now):
        return False
    output.append({"merged": prepared})
    return True
import unittest

from publisher import merge, publish


class PublicationQualificationTests(unittest.TestCase):
    def exercise(self, operation, change=None, entry_time=10, finish_time=19):
        owner = dict(scope="PUBLISHER", owner_id="a", token="t",
                     acquired_at=1, expires_at=20)
        clock = [entry_time]
        output = ["prior"]
        calls = []
        state_after_prepare = []

        def prepare(value):
            calls.append(value)
            clock[0] = finish_time
            if change:
                if callable(change):
                    change(owner)
                else:
                    owner.update(change)
            state_after_prepare.append(owner.copy())
            return "prepared:" + value

        initial_owner = owner.copy()
        result = operation("value", owner, prepare, lambda: clock[0], output)
        self.assertEqual(owner, state_after_prepare[0] if calls else initial_owner)
        return result, output, calls

    def test_prepare_crosses_expiry(self):
        for operation in (publish, merge):
            for finish_time in (20, 21):
                with self.subTest(operation=operation.__name__, finish=finish_time):
                    result, output, calls = self.exercise(operation, finish_time=finish_time)
                    self.assertIs(result, False)
                    self.assertEqual(output, ["prior"])
                    self.assertEqual(calls, ["value"])

    def test_identity_and_scope_changes_during_prepare(self):
        for operation in (publish, merge):
            for change in ({"owner_id": "b"}, {"token": "replacement"},
                           {"acquired_at": 2}, {"scope": "OTHER"}):
                with self.subTest(operation=operation.__name__, change=change):
                    result, output, _ = self.exercise(operation, change=change)
                    self.assertIs(result, False)
                    self.assertEqual(output, ["prior"])

    def test_expiry_shortened_during_prepare(self):
        for operation in (publish, merge):
            with self.subTest(operation=operation.__name__):
                result, output, _ = self.exercise(operation, change={"expires_at": 19})
                self.assertIs(result, False)
                self.assertEqual(output, ["prior"])

    def test_qualification_fields_removed_during_prepare(self):
        for operation in (publish, merge):
            for key in ("owner_id", "token", "acquired_at", "scope", "expires_at"):
                with self.subTest(operation=operation.__name__, removed=key):
                    result, output, _ = self.exercise(operation, change=lambda owner: owner.pop(key))
                    self.assertIs(result, False)
                    self.assertEqual(output, ["prior"])

    def test_expired_at_entry_does_not_prepare(self):
        for operation in (publish, merge):
            with self.subTest(operation=operation.__name__):
                result, output, calls = self.exercise(operation, entry_time=20)
                self.assertIs(result, False)
                self.assertEqual(output, ["prior"])
                self.assertEqual(calls, [])

    def test_valid_publication_preserves_output_shape(self):
        for operation, prepared_output in ((publish, "prepared:value"),
                                           (merge, {"merged": "prepared:value"})):
            with self.subTest(operation=operation.__name__):
                result, output, calls = self.exercise(operation)
                self.assertIs(result, True)
                self.assertEqual(output, ["prior", prepared_output])
                self.assertEqual(calls, ["value"])


if __name__ == "__main__":
    unittest.main()
